// Writes src/data/storyAudio.js — a static require() map of every bundled
// narration file. Metro can only bundle assets referenced by literal
// require() calls, so this file is generated from what's on disk.
//
// File naming: assets/audio/<filmId>-<age>[-<lang>].<m4a|mp3>
//   English has no language suffix (ddlj-3-5.m4a); others do (ddlj-3-5-hi.m4a).

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const AUDIO_DIR = path.join(ROOT, "assets", "audio");
const OUT_PATH = path.join(ROOT, "src", "data", "storyAudio.js");
const NAME_RE = /^(.+?)-(3-5|6-8|9-12)(?:-(hi|en-hi))?\.(m4a|mp3)$/;

function audioBaseName(filmId, age, lang = "en") {
  return lang === "en" ? `${filmId}-${age}` : `${filmId}-${age}-${lang}`;
}

function parseAudioName(file) {
  const m = file.match(NAME_RE);
  if (!m) return null;
  const [, filmId, age, lang = "en", ext] = m;
  return { filmId, age, lang, ext };
}

function writeAudioManifest() {
  const files = fs.existsSync(AUDIO_DIR) ? fs.readdirSync(AUDIO_DIR).sort() : [];
  const map = {}; // lang → film → age → file
  for (const file of files) {
    const p = parseAudioName(file);
    if (!p) continue;
    map[p.lang] ??= {};
    map[p.lang][p.filmId] ??= {};
    // Prefer the optimised .m4a when both exist.
    if (map[p.lang][p.filmId][p.age] && p.ext === "mp3") continue;
    map[p.lang][p.filmId][p.age] = file;
  }

  const lines = [
    "// Auto-generated by scripts/lib/audio-manifest.js — do not edit manually.",
    "// Regenerate with: node scripts/generate-stories.js (or scripts/optimize-audio.js)",
    "// Shape: STORY_AUDIO[language][filmId][ageRange]",
    "export const STORY_AUDIO = {",
  ];
  for (const lang of Object.keys(map).sort()) {
    lines.push(`  ${JSON.stringify(lang)}: {`);
    for (const filmId of Object.keys(map[lang]).sort()) {
      const entries = Object.entries(map[lang][filmId])
        .map(([age, file]) => `"${age}": require("../../assets/audio/${file}")`)
        .join(", ");
      lines.push(`    ${JSON.stringify(filmId)}: { ${entries} },`);
    }
    lines.push("  },");
  }
  lines.push("};", "");
  fs.writeFileSync(OUT_PATH, lines.join("\n"));
  return map;
}

module.exports = { writeAudioManifest, audioBaseName, parseAudioName };

if (require.main === module) {
  const map = writeAudioManifest();
  console.log(`Wrote src/data/storyAudio.js (${Object.keys(map).join(", ")})`);
}
